 var cards={strike:{name:'脉冲',cost:1,damage:9,text:'造成 9 伤害。'},guard:{name:'屏障',cost:1,block:9,text:'获得 9 护盾，抵挡本轮攻击。'},echo:{name:'回声',cost:1,text:'重复本回合上一张攻击或屏障的效果。'},focus:{name:'聚焦',cost:1,text:'下一张攻击 +6 伤害。'},shred:{name:'相位穿刺',cost:2,damage:18,pierce:true,text:'造成 18 伤害，穿过护盾。'},draw:{name:'快速采样',cost:1,text:'抽 2 张牌。'},mark:{name:'共振标记',cost:1,text:'目标两轮内受到的伤害 +50%。'},burst:{name:'频谱爆发',cost:2,damage:11,all:true,text:'对所有敌人造成 11 伤害。'},patch:{name:'紧急修复',cost:1,text:'恢复 6 生命；本场战斗后才归还。'},capacitor:{name:'蓄电',cost:0,block:4,text:'获得 4 护盾与 1 能量；本场消耗。'},drain:{name:'反向回收',cost:2,damage:13,text:'造成 13 伤害，并恢复 4 生命。'},counter:{name:'反射屏障',cost:1,block:6,text:'获得 6 护盾；本轮每次成功格挡后反击 6。'}};
 var kits={resonance:{name:'共振构筑',tip:'多一张回声。先攻击或架盾，再复制效果。'},bulwark:{name:'屏障构筑',tip:'以反射屏障替换脉冲，每轮开始获得 3 护盾。'},phase:{name:'穿透构筑',tip:'以相位穿刺替换脉冲，对抗高护盾目标。'}};
 var relics={amp:{name:'增幅芯片',text:'所有攻击 +2。'},battery:{name:'并联电池',text:'每轮能量 +1。'},memory:{name:'护盾记忆',text:'新回合保留上轮剩余护盾的一半。'},recovery:{name:'自修复晶体',text:'每场战斗胜利恢复 6 生命。'}};
 var enemyTypes={guard:{name:'防卫机',hp:34},drone:{name:'污染探针',hp:28},shooter:{name:'连射机',hp:32},elite:{name:'强化防卫机',hp:52},mirror:{name:'镜像监守',hp:76},warden:{name:'实验监管者',hp:98},core:{name:'零号核心',hp:126}};
 function create(seed,kit){kit=kits[kit]?kit:'resonance';var base=['strike','strike','strike','strike','guard','guard','guard','echo','focus','patch'];if(kit==='resonance')base[3]='echo';if(kit==='bulwark')base[3]='counter';if(kit==='phase')base[3]='shred';return{version:1,rng:seed>>>0,kit:kit,stage:0,phase:'route',hp:72,maxHp:72,coins:18,deck:base.map(function(kind,i){return{id:i,kind:kind,level:0};}),nextId:10,relics:[],enemies:[],draw:[],hand:[],discard:[],exhaust:[],turn:1,energy:3,reserve:0,shield:0,focus:0,counter:0,poison:0,sealed:0,last:null,target:0,offers:[],elite:false,message:'选择一条实验路线。敌人下一轮行动会提前显示。',recorded:false};}
 function cardById(s,id){return s.deck.find(function(c){return c.id===id;});}
 function has(s,id){return s.relics.indexOf(id)>=0;}
 function intent(s,e){var turn=s.turn;if(e.kind==='drone')return{type:'poison',damage:5+s.stage,poison:2,label:'攻击 '+(5+s.stage)+'，附加 2 污染'};if(e.kind==='shooter')return{type:'multi',damage:4+Math.floor(s.stage/3),count:3,label:'连续攻击 '+(4+Math.floor(s.stage/3))+' ×3'};if(e.kind==='mirror'&&turn%3===0)return{type:'seal',block:16,label:'架盾 16，封锁回声一轮'};if(e.kind==='core'&&turn%3===0)return{type:'multi',damage:7,count:3,label:'过载连射 7 ×3'};if(turn%3===0)return{type:'block',block:e.kind==='core'?22:12,label:'获得 '+(e.kind==='core'?22:12)+' 护盾'};var damage= e.kind==='warden'?(e.hp<50?18:12):e.kind==='core'?15:e.kind==='mirror'?11:e.kind==='elite'?10:7+Math.floor(s.stage/3);return{type:'attack',damage:damage,label:'攻击 '+damage};}
 function draw(s,count){for(var i=0;i<count;i++){if(!s.draw.length){s.draw=C.shuffle(s,s.discard);s.discard=[];}if(!s.draw.length)break;s.hand.push(s.draw.pop());}}
 function selectSurvivor(s){if(!s.enemies.some(function(e){return e.id===s.target&&e.hp>0;})){var next=s.enemies.find(function(e){return e.hp>0;});if(next)s.target=next.id;}}
 function newTurn(s){selectSurvivor(s);s.energy=3+(has(s,'battery')?1:0)+(s.reserve||0);s.reserve=0;s.shield=(has(s,'memory')?Math.floor(s.shield/2):0)+(s.kit==='bulwark'?3:0);s.focus=0;s.counter=0;s.last=null;draw(s,5);}
 function battle(s,elite){s.elite=!!elite;var kinds=s.stage===2?['mirror']:s.stage===5?['warden']:s.stage===8?['core']:s.stage>=6?['shooter','drone']:s.stage>=3?['guard','drone']:elite?['elite']:['guard'];s.enemies=kinds.map(function(kind,i){var def=enemyTypes[kind];return{id:i,kind:kind,hp:Math.round(def.hp*(elite&&s.stage%3!==2?1.35:1)),shield:kind==='elite'?8:0,vulnerable:0};});s.turn=1;s.target=0;s.reserve=0;s.phase='battle';s.draw=C.shuffle(s,s.deck.map(function(c){return c.id;}));s.hand=[];s.discard=[];s.exhaust=[];s.poison=0;s.sealed=0;newTurn(s);s.message='读取预告，再分配本轮能量。结束回合后，敌人执行显示的行动。';}
 function damage(s,e,value,pierce){if(!e||e.hp<=0)return;var amount=Math.round(value*(e.vulnerable>0?1.5:1));if(!pierce){var absorbed=Math.min(e.shield,amount);e.shield-=absorbed;amount-=absorbed;}e.hp=Math.max(0,e.hp-amount);}
 function clear(s){if(s.enemies.some(function(e){return e.hp>0;}))return false;s.coins+=s.elite?26:20;if(has(s,'recovery'))s.hp=Math.min(s.maxHp,s.hp+6);if(s.stage===8){s.phase='won';s.message='零号核心停止运行，九节点实验战役完成。';}else if(s.stage===2||s.stage===5){s.phase='relic';s.offers=C.shuffle(s,Object.keys(relics).filter(function(id){return !has(s,id);})).slice(0,3);s.message='监守已击败，选择一件持续整场实验的晶体。';}else{s.phase='reward';s.offers=C.shuffle(s,Object.keys(cards).filter(function(id){return id!=='strike'&&id!=='guard';})).slice(0,3);s.message='战斗胜利。添加一张牌，或保留研究资金。';}return true;}
 function advance(s){s.stage++;s.phase='route';s.offers=[];s.hand=[];s.draw=[];s.discard=[];s.exhaust=[];s.enemies=[];s.last=null;s.message='选择下一节点。构筑和生命会延续，不会在战斗之间重置。';}
 function play(s,id){if(s.phase!=='battle')return false;var index=s.hand.indexOf(id),card=cardById(s,id);if(index<0||!card)return false;var def=cards[card.kind],cost=def.cost,boost=card.level?3:0;if(s.energy<cost)return false;if(card.kind==='echo'&&(!s.last||s.sealed>0)){s.message=s.sealed>0?'镜像封锁生效，本回合不能使用回声。':'先使用攻击或屏障，再使用回声。';return true;}var target=s.enemies.find(function(e){return e.id===s.target&&e.hp>0;})||s.enemies.find(function(e){return e.hp>0;});s.energy-=cost;s.hand.splice(index,1);(card.kind==='patch'||card.kind==='capacitor'?s.exhaust:s.discard).push(id);
  if(def.damage){var value=def.damage+boost+(has(s,'amp')?2:0)+s.focus;s.focus=0;(def.all?s.enemies:[target]).forEach(function(e){damage(s,e,value,def.pierce);});s.last={type:'damage',value:value,pierce:!!def.pierce,all:!!def.all};}
  if(def.block){var block=def.block+boost;s.shield+=block;s.last={type:'block',value:block};}
  if(card.kind==='echo'){if(s.last.type==='damage')(s.last.all?s.enemies:[target]).forEach(function(e){damage(s,e,s.last.value+boost,s.last.pierce);});else s.shield+=s.last.value+boost;}
  if(card.kind==='focus')s.focus+=6+boost;
  if(card.kind==='draw')draw(s,card.level?3:2);
  if(card.kind==='mark')target.vulnerable=card.level?3:2;
  if(card.kind==='patch')s.hp=Math.min(s.maxHp,s.hp+6+boost);
  if(card.kind==='capacitor')s.energy=Math.min(8,s.energy+1);
  if(card.kind==='counter')s.counter=6+boost;
  if(card.kind==='drain')s.hp=Math.min(s.maxHp,s.hp+4+(card.level?2:0));
  s.message=def.name+'已使用。剩余能量 '+s.energy+'。';clear(s);selectSurvivor(s);return true;
 }
 function endTurn(s){if(s.phase!=='battle')return false;var sealed=false;s.enemies.forEach(function(e){if(e.hp<=0||s.hp<=0)return;var plan=intent(s,e);if(plan.block)e.shield+=plan.block;if(plan.type==='seal')sealed=true;if(plan.damage){for(var i=0;i<(plan.count||1);i++){var absorbed=Math.min(s.shield,plan.damage);s.shield-=absorbed;s.hp=Math.max(0,s.hp-(plan.damage-absorbed));if(absorbed>0&&s.counter)damage(s,e,s.counter,false);if(e.hp<=0||s.hp<=0)break;}if(plan.poison)s.poison+=plan.poison;}e.vulnerable=Math.max(0,e.vulnerable-1);});if(s.poison>0){s.hp=Math.max(0,s.hp-s.poison);s.poison=Math.max(0,s.poison-1);}s.discard.push.apply(s.discard,s.hand);s.hand=[];if(s.hp<=0){s.phase='lost';s.message='实验失败。构筑已记录，可以开始新的路线。';return true;}if(clear(s))return true;s.turn++;s.sealed=sealed?1:0;newTurn(s);s.message='第 '+s.turn+' 回合。污染无视护盾；优先关闭污染探针。';return true;}
 function act(s,action,d){if(action==='target'&&s.phase==='battle'){var e=s.enemies.find(function(e){return e.id===Number(d.enemy)&&e.hp>0;});if(!e)return false;s.target=e.id;return true;}if(action==='play')return play(s,Number(d.card));if(action==='end')return endTurn(s);if(action==='bankEnd'&&s.phase==='battle'&&s.energy>0){s.reserve=Math.min(2,s.energy);return endTurn(s);}
  if(s.phase==='route'&&action==='route'){if([1,4,7].indexOf(s.stage)>=0){s.phase='camp';s.message='研究间：修复、强化或精简卡组，三选一后继续。';}else battle(s,d.choice==='elite');return true;}
  if(s.phase==='reward'&&(action==='reward'||action==='skip')){if(action==='reward'){if(s.offers.indexOf(d.choice)<0)return false;s.deck.push({id:s.nextId++,kind:d.choice,level:0});}else s.coins+=12;advance(s);return true;}
  if(s.phase==='relic'&&action==='relic'){if(s.offers.indexOf(d.choice)<0)return false;s.relics.push(d.choice);advance(s);return true;}
  if(s.phase==='camp'){if(action==='rest'){s.hp=Math.min(s.maxHp,s.hp+6);advance(s);return true;}if(action==='heal'&&s.coins>=10&&s.hp<s.maxHp){s.coins-=10;s.hp=Math.min(s.maxHp,s.hp+20);advance(s);return true;}var card=cardById(s,Number(d.card));if(!card)return false;if(action==='upgrade'&&card.level===0&&s.coins>=18){s.coins-=18;card.level=1;advance(s);return true;}if(action==='remove'&&s.deck.length>6&&s.coins>=16){s.coins-=16;s.deck=s.deck.filter(function(c){return c.id!==card.id;});advance(s);return true;}}
  return false;
 }
 function score(s){return s.stage*100+s.coins+(s.phase==='won'?500:0);}
 function valid(s){if(!s||s.version!==1||!kits[s.kit]||!C.integer(s.rng,0,0xffffffff)||!C.integer(s.stage,0,8)||['route','battle','reward','relic','camp','won','lost'].indexOf(s.phase)<0||typeof s.recorded!=='boolean'||typeof s.message!=='string'||s.message.length>500)return false;
  var bounds={hp:100,maxHp:100,coins:10000,nextId:1000,turn:10000,energy:8,shield:1000,focus:100,counter:100,poison:100,sealed:1,target:3};if(!Object.keys(bounds).every(function(k){return C.integer(s[k],0,bounds[k]);})||s.hp>s.maxHp||!Array.isArray(s.deck)||s.deck.length<6||s.deck.length>60||!s.deck.every(function(c){return c&&C.integer(c.id,0,999)&&c.id<s.nextId&&cards[c.kind]&&C.integer(c.level,0,1);})||new Set(s.deck.map(function(c){return c.id;})).size!==s.deck.length)return false;
  if(!Array.isArray(s.enemies)||s.enemies.length>3||!s.enemies.every(function(e){return e&&enemyTypes[e.kind]&&C.integer(e.id,0,2)&&C.integer(e.hp,0,200)&&C.integer(e.shield,0,1000)&&C.integer(e.vulnerable,0,3);}))return false;
  if(!Array.isArray(s.relics)||!s.relics.every(function(r){return relics[r];})||new Set(s.relics).size!==s.relics.length||!Array.isArray(s.offers)||s.offers.length>3||!s.offers.every(function(id){return cards[id]||relics[id];}))return false;
  if(s.reserve!==undefined&&!C.integer(s.reserve,0,2))return false;
  var zones=[];if(!['hand','draw','discard','exhaust'].every(function(k){if(!Array.isArray(s[k])||s[k].length>60||!s[k].every(function(id){return C.integer(id,0,999)&&cardById(s,id);}))return false;zones=zones.concat(s[k]);return true;}))return false;if(s.phase==='battle'&&(zones.length!==s.deck.length||new Set(zones).size!==zones.length))return false;
  return !s.last||['damage','block'].indexOf(s.last.type)>=0&&C.integer(s.last.value,0,300);
 }
 function preview(s,id){if(s.phase!=='battle')return null;var copy=JSON.parse(JSON.stringify(s));if(id===undefined){endTurn(copy);return{hp:copy.hp,poison:copy.poison,phase:copy.phase};}var card=cardById(s,id);if(!card||s.hand.indexOf(id)<0||s.energy<cards[card.kind].cost||card.kind==='echo'&&(!s.last||s.sealed>0))return null;if(!play(copy,id))return null;return{energy:copy.energy,hp:copy.hp-s.hp,shield:copy.shield-s.shield,enemies:s.enemies.filter(function(e){return e.hp>0;}).map(function(e){var after=copy.enemies.find(function(a){return a.id===e.id;});return{id:e.id,name:enemyTypes[e.kind].name,hp:e.hp-after.hp,shield:e.shield-after.shield,mark:after.vulnerable-e.vulnerable};}),focus:copy.focus-s.focus,draw:copy.hand.length-(s.hand.length-1)};}
 function previewText(s,card){var p=preview(s,card.id);if(!p)return card.kind==='echo'&&s.sealed>0?'回声被封锁。':card.kind==='echo'&&!s.last?'先使用攻击或屏障。':'能量不足。';var parts=[];p.enemies.forEach(function(e){if(e.hp||e.shield)parts.push(e.name+'：'+(e.shield?'盾 −'+e.shield+'，':'')+'生命 −'+e.hp);if(e.mark>0)parts.push(e.name+'：标记 '+(card.level?3:2)+' 轮');});if(p.hp)parts.push('生命 +'+p.hp);if(p.shield)parts.push('护盾 +'+p.shield);if(p.focus)parts.push('下次攻击 +'+p.focus);if(p.draw)parts.push('抽牌 '+p.draw);return parts.join('；')||'按卡牌效果结算。';}
 function enemyMarkup(s){return '<div class="campaignTargets" aria-label="敌情与目标">'+s.enemies.filter(function(e){return e.hp>0;}).map(function(e){return '<article class="campaignEnemy '+(e.id===s.target?'isSelected':'')+'"><h3>'+enemyTypes[e.kind].name+'</h3><p>生命 '+e.hp+' · 护盾 '+e.shield+(e.vulnerable?' · 标记 '+e.vulnerable+' 轮':'')+'</p><p>'+intent(s,e).label+'</p>'+B('target',e.id===s.target?'当前目标':'选择目标',s.phase!=='battle','data-enemy="'+e.id+'" aria-pressed="'+(e.id===s.target)+'"')+'</article>';}).join('')+'</div>';}
 function cardText(card){if(!card.level)return cards[card.kind].text;var upgraded={strike:'造成 12 伤害。',guard:'获得 12 护盾，抵挡本轮攻击。',echo:'重复本回合上一张攻击或屏障，并增加 3 伤害或护盾。',focus:'下一张攻击 +9 伤害。',shred:'造成 21 伤害，穿过护盾。',draw:'抽 3 张牌。',mark:'目标三轮内受到的伤害 +50%。',burst:'对所有敌人造成 14 伤害。',patch:'恢复 9 生命；本场战斗后才归还。',capacitor:'获得 7 护盾与 1 能量；本场消耗。',drain:'造成 16 伤害，并恢复 6 生命。',counter:'获得 9 护盾；本轮每次成功格挡后反击 9。'};return upgraded[card.kind];}
 function cardMarkup(card,action,disabled,s){var def=cards[card.kind];return '<article class="campaignCard"><span class="campaignNote">能量 '+def.cost+(card.level?' · 已强化':'')+'</span><h3>'+def.name+(card.level?' +':'')+'</h3><p>'+cardText(card)+'</p>'+(s?'<p class="campaignPreview">'+E(previewText(s,card))+'</p>':'')+B(action,action==='play'?'使用':action==='upgrade'?'强化 ·18':'移除 ·16',disabled,'data-card="'+card.id+'"')+'</article>';}
 function view(s,meta,warn){if(!s)return '<div class="campaignPane"><h3>九节点构筑战役</h3><p>读取敌人意图，用有限能量组合卡牌。在战斗之间选牌、强化和精简，击败三位实验监守。</p><div class="campaignChoices">'+Object.entries(kits).map(function(pair){return '<article class="campaignChoice"><h3>'+pair[1].name+'</h3><p>'+pair[1].tip+'</p>'+B('start','选择构筑',false,'data-choice="'+pair[0]+'"')+'</article>';}).join('')+'</div><p class="campaignNote">通关 '+meta.clears+' 次 · 最高 '+meta.best+'。卡牌、路线和每次行动自动保存。</p>'+(warn?'<p class="campaignWarning">'+E(warn)+'</p>':'')+'</div>';
  var progress='<div class="campaignProgress">'+Array.from({length:9},function(_,i){return '<span class="'+(i<s.stage?'isDone':i===s.stage?'isCurrent':'')+'">'+(i+1)+(i%3===2?'监守':i%3===1?'研究':'交战')+'</span>';}).join('')+'</div>',content='';
  if(s.phase==='route')content='<h3>选择实验节点</h3>'+([1,4,7].indexOf(s.stage)>=0?B('route','进入研究间',false):s.stage%3===2?B('route','挑战监守',false):'<div class="campaignChoices"><article class="campaignChoice"><h3>常规交战</h3><p>标准敌群，战后获得 20 资金和一张卡牌选择。</p>'+B('route','进入交战',false,'data-choice="battle"')+'</article><article class="campaignChoice"><h3>强化实验</h3><p>首节点守卫强化，奖励 26 资金。后续为双敌群；选牌决定下一战能力。</p>'+B('route','高风险交战',false,'data-choice="elite"')+'</article></div>');
  if(s.phase==='battle'){var forecast=preview(s);content='<h3>第 '+s.turn+' 回合</h3>'+enemyMarkup(s)+'<div class="campaignTurnBar"><span>能量 '+s.energy+' · 护盾 '+s.shield+'</span><div class="campaignToolbar">'+B('end','结束回合',false)+B('bankEnd','蓄能结束',s.energy<1)+'</div><span class="campaignNote">直接结束后：生命 '+s.hp+' → '+forecast.hp+(forecast.poison?' · 污染 '+forecast.poison:'')+(forecast.phase==='lost'?' · 会失败':'')+'</span></div><div class="campaignDeck campaignHand">'+s.hand.map(function(id){var card=cardById(s,id);return cardMarkup(card,'play',s.energy<cards[card.kind].cost||card.kind==='echo'&&(!s.last||s.sealed>0),s);}).join('')+'</div><p class="campaignNote">蓄能结束会执行敌人行动，并将最多 2 点未用能量转到下一回合。抽牌 '+s.draw.length+' · 弃牌 '+s.discard.length+' · 暂时消耗 '+s.exhaust.length+'。结束会弃掉剩余手牌；护盾默认不跨回合。</p>'; }
  if(s.phase==='reward')content='<h3>选择战利品</h3><div class="campaignChoices">'+s.offers.map(function(id){return '<article class="campaignCard"><span class="campaignNote">能量 '+cards[id].cost+'</span><h3>'+cards[id].name+'</h3><p>'+cards[id].text+'</p>'+B('reward','加入卡组',false,'data-choice="'+id+'"')+'</article>';}).join('')+'</div><div class="campaignToolbar">'+B('skip','跳过 ·资金+12',false)+'</div>';
  if(s.phase==='relic')content='<h3>选择持续晶体</h3><div class="campaignChoices">'+s.offers.map(function(id){return '<article class="campaignChoice"><h3>'+relics[id].name+'</h3><p>'+relics[id].text+'</p>'+B('relic','安装晶体',false,'data-choice="'+id+'"')+'</article>';}).join('')+'</div>';
  if(s.phase==='camp')content='<h3>研究间 · 只进行一项</h3><div class="campaignToolbar">'+B('heal','修复20 ·资金10',s.coins<10||s.hp>=s.maxHp)+B('rest','休息 ·生命+6',false)+'</div><div class="campaignDeck">'+s.deck.map(function(card){var def=cards[card.kind];return '<article class="campaignCard"><h3>'+def.name+(card.level?' +':'')+'</h3><p>'+cardText(card)+'</p><div class="campaignToolbar">'+B('upgrade','强化 ·18',card.level>0||s.coins<18,'data-card="'+card.id+'"')+B('remove','移除 ·16',s.deck.length<=6||s.coins<16,'data-card="'+card.id+'"')+'</div></article>';}).join('')+'</div>';
  if(s.phase==='won'||s.phase==='lost')content='<h3>'+(s.phase==='won'?'实验战役完成':'实验终止')+'</h3><p>节点 '+(s.stage+1)+' /9 · 记录 '+score(s)+' · 卡组 '+s.deck.length+' 张</p>'+B('start','开始新实验',false,'data-choice="'+s.kit+'"');
  return '<div class="campaignMetrics"><span>生命 <b>'+s.hp+'/'+s.maxHp+'</b></span><span>研究资金 <b>'+s.coins+'</b></span><span>卡组 <b>'+s.deck.length+'</b></span><span>污染 <b>'+s.poison+'</b></span></div>'+progress+'<div class="campaignLayout"><section class="campaignPane">'+content+'<div class="campaignLog" role="status">'+E(warn||s.message)+'</div></section><aside class="campaignPane">'+(s.phase==='battle'?'':'<h3>敌人行动预告</h3>'+enemyMarkup(s))+'<h3>持续晶体</h3>'+(s.relics.length?s.relics.map(function(id){return '<p class="campaignNote">'+relics[id].name+'：'+relics[id].text+'</p>';}).join(''):'<p class="campaignNote">击败监守后获得，整场实验保留。</p>')+'<details><summary>卡组详情 ·'+s.deck.length+' 张</summary>'+s.deck.map(function(c){return '<p class="campaignNote">'+cards[c.kind].name+(c.level?' +':'')+' · '+cardText(c)+'</p>';}).join('')+'</details><p class="campaignNote">先选目标，再使用攻击。标记影响后续伤害；回声复制本回合最近的攻击或屏障。污染无视护盾。</p></aside></div>';
 }
 var api={create:create,act:act,play:play,endTurn:endTurn,battle:battle,intent:intent,score:score,valid:valid,cards:cards,preview:preview};root.XXSXEchoDeck=api;C.mount('echoDeck','xxsxEchoDeckV1',api,view);
